/**
 * Use case SelectMenuOption (legacy PAGOMNU, paragraph 2000-ELEGIR-OPCION, EVALUATE OPCIONI).
 *
 * RULE-006:
 *  - '1'   -> XCTL to PAGOORD (destination "PAGOORD").
 *  - '9'   -> PERFORM 9000-TERMINAR. The source defines no destination value for this branch
 *             (UNRESOLVED_FUNCTIONAL_INFORMATION), so the destination is left null and no error is raised.
 *  - other -> MENSAJEO = 'OPCION NO VALIDA' (rejected with INVALID_OPTION).
 *
 * A missing (null), empty or blank option is neither '1' nor '9', so it falls to WHEN OTHER.
 */
public class SelectMenuOptionService {

    public SelectMenuOptionService() {
    }

    public SelectMenuOptionResponse execute(SelectMenuOptionRequest request) {
        String option = request == null ? null : request.option();

        if ("1".equals(option)) {
            return new SelectMenuOptionResponse("PAGOORD");
        }
        if ("9".equals(option)) {
            return new SelectMenuOptionResponse(null);
        }
        throw new BusinessError("INVALID_OPTION", "-1", "OPCION NO VALIDA");
    }
}
